svg.script:
(function(){
'use strict';
/* Goop-as-SVG shim: makes an SVG document behave like an HTML document for the page inside the foreignObject. */
var X='http://www.w3.org/1999/xhtml',D=Document.prototype;
function def(o,k,d){d.configurable=true;Object.defineProperty(o,k,d)}
function first(n){return document.getElementsByTagNameNS(X,n)[0]||null}
var rootGet=Object.getOwnPropertyDescriptor(D,'documentElement').get;
def(document,'documentElement',{get:function(){return first('html')||rootGet.call(document)}});
def(document,'body',{get:function(){return first('body')}});
def(document,'head',{get:function(){return first('head')}});
def(document,'scrollingElement',{get:function(){return first('html')}});
def(document,'createElement',{value:function(n){return document.createElementNS(X,String(n).toLowerCase())}});
function upper(proto,key){
  var g=Object.getOwnPropertyDescriptor(proto,key).get;
  def(proto,key,{get:function(){var v=g.call(this);return this.namespaceURI===X?v.toUpperCase():v}});
}
upper(Element.prototype,'tagName');upper(Node.prototype,'nodeName');
function parse(markup){
  var d=new DOMParser().parseFromString('<!doctype html><body>'+markup,'text/html');
  return Array.prototype.map.call(d.body.childNodes,function(n){return document.importNode(n,true)});
}
var ih=Object.getOwnPropertyDescriptor(Element.prototype,'innerHTML');
def(HTMLElement.prototype,'innerHTML',{get:function(){return ih.get.call(this)},set:function(v){this.replaceChildren.apply(this,parse(String(v)))}});
var tpl=new WeakMap();
def(HTMLTemplateElement.prototype,'content',{get:function(){
  var f=tpl.get(this);
  if(!f){f=document.createDocumentFragment();parse(this.getAttribute('data-goop-tpl')||'').forEach(function(n){f.append(n)});tpl.set(this,f)}
  return f;
}});
window.scrollTo=function(x,y){
  var h=first('html');if(!h)return;
  if(x&&typeof x==='object'){y=x.top;x=x.left}
  h.scrollLeft=x||0;h.scrollTop=y||0;
};
})();

body.script:
window.goopPrograms=Object.create(null);
;
// The builds inline this configuration. A local gateway serves its own API.
window.GOOP_BACKEND_URL ||= ['localhost','127.0.0.1','[::1]'].includes(location.hostname)
  ? location.origin : 'https://goop-gateway2.onrender.com';
window.GOOP_BLOX_URL ||= 'https://goop-blox.onrender.com';

;
const playerAccount = (() => {
  let session=null, collection, state=null, previous=new Map(), running=null, message='';
  const listeners=new Set();
  const key=item=>JSON.stringify(item.kind==='favorite'?[item.kind,item.source,item.name]:[item.kind,item.url]);
  const map=items=>new Map(items.map(item=>[key(item),item]));
  const changed=()=>listeners.forEach(fn=>fn());
  const storeKey=()=> 'goop-sync-v1:'+session.uid;
  function persist(){try{localStorage.setItem(storeKey(),JSON.stringify(state));}catch{message='Device storage is unavailable. Keep this page open until syncing finishes.';}}
  function localChange(){
    if(!collection)return;
    const next=map(collection.get());
    if(session && state){
      let dirty=false;
      for(const [id,item] of next){
        if(JSON.stringify(previous.get(id))!==JSON.stringify(item)){stage('put',item);dirty=true;}
      }
      for(const [id,item] of previous){
        if(!next.has(id)){stage('remove',item);dirty=true;}
      }
      if(dirty){persist();void sync();}
    }
    previous=next;
  }
  function stage(op,item){state.pending[key(item)]={op,item,nonce:crypto.randomUUID()};}
  async function sync(){
    if(!session||!state||running||!collection)return;
    const user=session, work=state, task={};running=task;
    const current=()=>session===user && state===work;
    try{
      if(work.seed){
        const existing=map((await user.api('player-items')).items);
        if(!current())return;
        for(const item of work.seed)if(!existing.has(key(item)) && !work.pending[key(item)])stage('put',item);
        delete work.seed;persist();
      }
      while(current()){
        const batch=Object.entries(work.pending).slice(0,6);
        if(!batch.length)break;
        await user.api('player-items',{changes:batch.map(([,v])=>({op:v.op,item:v.item}))});
        if(!current())return;
        for(const [id,v] of batch)if(work.pending[id]?.nonce===v.nonce)delete work.pending[id];
        persist();
      }
      if(!current())return;
      const remote=await user.api('player-items');
      if(!current())return;
      const items=map(remote.items);
      for(const [id,v] of Object.entries(work.pending)){if(v.op==='remove')items.delete(id);else items.set(id,v.item);}
      collection.apply([...items.values()]);previous=map(collection.get());message='Bookmarks and favorite games are synced.';
    }catch(error){if(current())message='Sync paused. '+error.message;}
    finally{
      if(running===task)running=null;
      changed();
      if(current() && !message.startsWith('Sync paused') && Object.keys(work.pending).length)queueMicrotask(sync);
      else if(!current() && session && state && !running)queueMicrotask(sync);
    }
  }
  function login(uid,api){
    if(session?.uid===uid)return;
    const identity={uid,api(...args){if(session!==identity)throw Error('Sign in again to continue.');return api(...args);}};
    session=identity;state=null;running=null;message='';
    try{const value=JSON.parse(localStorage.getItem(storeKey()));if(value?.pending && typeof value.pending==='object')state=value;}catch{}
    if(collection)previous=map(collection.get());
    changed();void sync();
  }
  function logout(){session=null;state=null;running=null;message='';changed();}
  function toggle(){
    if(!session)return;
    if(state){
      state=null;message='Sync is off on this device.';
      try{localStorage.removeItem(storeKey());}catch{message='Sync is off for this visit. Device storage is unavailable.';}
    }
    else {state={pending:{},seed:collection.get()};persist();message='Syncing…';void sync();}
    changed();
  }
  window.addEventListener('online',sync);
  document.addEventListener('visibilitychange',()=>{if(!document.hidden)void sync()});
  setInterval(()=>{if(!document.hidden)void sync()},45000);
  return {login,logout,localChange,toggle, sync, listen(fn){listeners.add(fn);return ()=>listeners.delete(fn);},
    bind(value){collection=value;previous=map(value.get());}, get account(){return session;},get enabled(){return !!state;},
    get status(){return message||(session?(state?'Syncing…':'Sync is off on this device.'):'Sign in to Chat to sync bookmarks and favorite games.');}};
})();

;
window.goopPrograms["home"] = function(root, goopNavigate) {


let homeController;
(()=>{'use strict';
const $=id=>root.querySelector("#"+id) || document.getElementById(id), defaults={engine:'https:\/\/lite.duckduckgo.com/lite/?q=',wisp:'wss:\/\/itcode.vip/api/',customWisp:'',preferProxy:true,gameHost:'',moviesBase:'',musicBase:'',mangaBase:'',bloxBase:'',mangaSource:'mangadex',transport:'libcurl'};
const sources={ugs:{label:'UGS',owner:'gmshelf',file:'ugs.json'},seraph:{label:'Seraph',owner:'gmshelf',file:'seraph.json'},truffled:{label:'Truffled',owner:'gmshelf',file:'truffled.json'},ckv:{label:'CKV',owner:'gmshelf',file:'ckv.json'},fourgames:{label:'4Games',owner:'electricxmaxx',repo:'mathassignments',file:'math.json'}};
const cats=[['games','Games','',''],['movies','Movies','',''],['music','Music','',''],['manga','Manga','',''],['blox','GoopBlox','',''],['ai','AI','',''],['chat','Chat','',''],['settings','Settings','','']];
let settings={...defaults,...read('goop-settings',{})};if(!settings.noswMigration){if(settings.wisp==='wss:\/\/wisp.mercurywork.shop/')settings.wisp=defaults.wisp;settings.noswMigration=true;}if(settings.engine==='https:\/\/duckduckgo.com/?q=')settings.engine='https:\/\/lite.duckduckgo.com/lite/?q=';const defaultBookmarks = [...$('bookmarks').querySelectorAll('[data-bookmark-url]')].map(b=>({name:b.textContent,url:b.dataset.bookmarkUrl}));
let bookmarks=cleanBookmarks(read('goop-bookmarks',null)) ?? cleanBookmarks(defaultBookmarks);let active='home',gameSource='ugs',gameCache={};let gameSort='default',gameFavOnly=false,goopLastMovie=null;
if(!['libcurl','epoxy'].includes(settings.transport))settings.transport=defaults.transport;
function read(key,fallback){try{let value=JSON.parse(localStorage.getItem(key));return value??fallback}catch{return fallback}}
function save(){playerAccount.localChange();try{localStorage.setItem('goop-settings',JSON.stringify(settings));localStorage.setItem('goop-bookmarks',JSON.stringify(bookmarks))}catch{toast('Changes are available for this visit.')}}
function safeUrl(s){try{const u=new URL(s);return ['http:','https:'].includes(u.protocol)?u.href:null}catch{return null}}
function validBase(s){return safeUrl(s?.trim()||'')}
function toast(s){const el=$('toast');el.textContent=s;el.classList.remove('hidden');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.add('hidden'),3500)}
function view(v){
 const changed=active!==v;
 if(currentGame && v!=='category')closeCatalogGame();
 if(v!=='home')hideResults();

 active=v;
 highlightSection(v==='home'||v==='settings'?v:'');
 if(v!=='category'){
   $('goopCommunity')?.remove();
   $('goopAIChat')?.remove();
 }
 const views={home:'home',category:'categoryView',settings:'settingsView'};
 for(const id of Object.values(views))$(id).classList.toggle('hidden',id!==views[v]);
 window.scrollTo(0,0);
 if((changed || v==='category' || v==='browser') && !matchMedia('(prefers-reduced-motion: reduce)').matches){
   const panel=$(views[v]);
   (panel.getAnimations?.() || []).filter(a=>a.id==='goop-view-entry').forEach(a=>a.cancel());
   panel.animate?.([{opacity:0.84,translate:'0 3px'},{opacity:1,translate:'0 0'}],
     {id:'goop-view-entry',duration:140,easing:'ease-out'});
 }
}
function home(){goopNavigate('home');}$('homeBtn').onclick=home;$('brandHome').onclick=home;$('brandHome').onkeydown=e=>{if(e.key==='Enter')home()};document.querySelectorAll('[data-home]').forEach(b=>b.onclick=home);$('settingsBtn').onclick=()=>{goopNavigate('settings')};
function cleanBookmarks(list) {
  if (!Array.isArray(list)) return null;
  return list.flatMap(item => {
    const url = typeof item === 'string' ? item : item?.url || item?.href;
    const href = typeof url === 'string' && safeUrl(url);
    if (!href) return [];
    const label = typeof item === 'object' && (item.name || item.title);
    return [{name: String(label || new URL(href).hostname).slice(0, 55), url:href}];
  });
}
function renderBookmarks() {
  const list = $('bookmarks');
  const elements = bookmarks.map((item, i) => {
    const row = document.createElement('div');
    row.className = 'bookmark';
    const open = document.createElement('button');
    open.className = 'bookmark-name'; open.type='button'; open.textContent = item.name;
    open.onclick = () => navigate(item.url);
    const remove = document.createElement('button');
    remove.type = 'button'; remove.className = 'remove'; remove.textContent = '×';
    remove.setAttribute('aria-label', 'Remove ' + item.name);
    remove.onclick = () => {bookmarks.splice(i,1); save(); renderBookmarks();};
    row.append(open,remove);
    return row;
  });
  if (!elements.length) {
    const empty = document.createElement('p');
    empty.className = 'small'; empty.textContent = 'Your saved bookmarks will appear here.';
    elements.push(empty);
  }
  list.replaceChildren(...elements);
}
const editor = $('bookmarkEditor');
function editBookmark(url='') {
  document.body.append(editor);
  $('bookmarkForm').reset();
  $('bookmarkUrl').value = url;
  $('bookmarkName').value = url ? new URL(url).hostname : '';
  editor.showModal();
  $(url?'bookmarkName':'bookmarkUrl').focus();
}
$('bookmarkUrl').oninput = () => $('bookmarkUrl').setCustomValidity('');
$('bookmarkCancel').onclick = () => editor.close();
$('bookmarkForm').onsubmit = event => {
  event.preventDefault();
  const entered = $('bookmarkUrl').value.trim();
  const url = safeUrl(entered.includes(':') ? entered : 'https:\/\/'+entered);
  if (!url) {
    $('bookmarkUrl').setCustomValidity('Enter an http or https web address.');
    $('bookmarkUrl').reportValidity();return;
  }
  const name = $('bookmarkName').value.trim() || new URL(url).hostname;
  bookmarks.push({name:name.slice(0,55),url});
  editor.close(); save(); renderBookmarks();
};
$('addBookmark').onclick = () => editBookmark();
$('importBookmarks').onchange = async event => {
  const input = event.target, file = input.files[0];
  if (!file) return;
  try {
    const data = JSON.parse(await file.text());
    const entries = cleanBookmarks(Array.isArray(data)?data:data.bookmarks);
    if (!entries) throw Error();
    const urls = new Set(bookmarks.map(b=>b.url));
    const fresh = entries.filter(b=>{if(urls.has(b.url))return false;urls.add(b.url);return true;});
    bookmarks.push(...fresh); renderBookmarks(); save();
    $('importStatus').textContent = fresh.length + ' bookmark' + (fresh.length===1?'':'s') + ' added.';
  } catch { $('importStatus').textContent = 'Choose a Goop bookmarks backup (.json).'; }
  finally { input.value = ''; }
};

function highlightSection(id){
 for(const b of $('goopNav').children){if(b.dataset.goopSection===id)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')}
}
function resolveSearch(s){s=s.trim();if(!s)return null;if(/^https?:[/][/]/i.test(s))return safeUrl(s);if(/^localhost(:\d+)?(\/|$)/i.test(s))return 'http:\/\/'+s;if(/^(?:[\w-]+\.)+[a-z]{2,}(:\d+)?(\/.*)?$/i.test(s))return safeUrl('https:\/\/'+s);return settings.engine+encodeURIComponent(s)}
$('homeSearchForm').onsubmit=e=>{e.preventDefault();const u=resolveSearch($('homeSearch').value);if(u)navigate(u)};
// Decide using navigation URLs only. Account form contents are never needed here.
const goopYouTube = (() => {
  function url(value, base) {
    try {
      const target = new URL(value, base || undefined);
      if (/^https?:$/.test(target.protocol) && !target.username && !target.password && !target.port) return target;
    } catch {}
    return null;
  }
  function isYouTube(value) {
    const host = url(value)?.hostname;
    return host === 'youtu.be' || host === 'youtube.com' || host?.endsWith('.youtube.com') || false;
  }
  function isSignIn(value, from) {
    const u = url(value, from);
    if (!u) return false;
    if (u.hostname === 'accounts.youtube.com') return /^\/(?:accounts\/)?(?:ServiceLogin|AccountChooser|signin|login)(?:\/|$)/i.test(u.pathname);
    if (isYouTube(u.href)) return /^\/(?:signin|login)(?:\/|$)/i.test(u.pathname);
    if (u.hostname !== 'accounts.google.com') return false;
    const accountPage = u.pathname === '/' || /^\/(?:v[0-9]+\/)?(?:ServiceLogin|AccountChooser|InteractiveLogin|signin|login|o\/oauth2)(?:\/|$)/i.test(u.pathname);
    if (!accountPage) return false;
    return isYouTube(from) || u.searchParams.get('service') === 'youtube' || isYouTube(u.searchParams.get('continue'));
  }
  // NoSW renders the visited document in this frame. Its navigation hooks use
  // the virtual page URL because the actual document can be an about:srcdoc.
  function guard(frame, startingURL, onBlocked) {
    let previous = startingURL(), attached;
    function pageURL() {
      try {
        const w = frame.contentWindow;
        return url(w?.__u22?.location?.href || w?.__u22$url)?.href || '';
      } catch { return ''; }
    }
    function check(value, displayed = false) {
      if (!value) return false;
      if (!isSignIn(value, previous) && !isSignIn(value, pageURL())) return false;
      onBlocked(displayed);
      return true;
    }
    function attach() {
      const current = pageURL();
      if (check(current, true)) return;
      if (current) previous = current;
      let doc;
      try { doc = frame.contentDocument; } catch { return; }
      if (!doc || attached === doc) return;
      attached = doc;
      function intercept(event) {
        let destination;
        if (event.type === 'submit') destination = event.submitter?.getAttribute('formaction') || event.target.getAttribute('action');
        else {
          const link = event.composedPath().find(node => node.matches?.('a[href],area[href]'));
          destination = link?.getAttribute('href');
          if (!destination && link) destination = link.href;
        }
        if (!destination) return;
        const base = pageURL() || previous;
        const target = url(destination, base);
        if (!target || !check(target.href)) return;
        event.preventDefault();
        event.stopImmediatePropagation();
      }
      for (const type of ['click','auxclick','submit']) doc.defaultView.addEventListener(type,intercept,true);
    }
    // Script-driven navigation in the rewritten page uses the shell's public loader.
    // Stop sign-in documents here as well, including an unexpected redirect to sign-in.
    const loader = frame.ownerDocument.defaultView.u22Loader;
    if (typeof loader?.loadDocument === 'function') {
      const load = loader.loadDocument.bind(loader);
      const handled = () => ({kind:'none',status:204,finalUrl:'about:blank'});
      loader.loadDocument = async (destination, options) => {
        if (check(destination)) return handled();
        const result = await load(destination, options);
        return check(result?.finalUrl) ? handled() : result;
      };
    }
    frame.addEventListener('load',attach);
    attach();
    return {check, remember(value){ if (value) previous = value; }};
  }
  return {isSignIn,guard};
})();

const tabs = [];
const tabButtons = document.getElementById('webTabButtons');
const pageContent = document.getElementById('goopPage');
const webContent = document.getElementById('webContent');
let selectedTab = null;

function setTitle(tab, title) {
  tab.label.textContent = title;
  tab.close.title = 'Close ' + title;
}

function createTab() {
  const chip = document.createElement('span');
  const label = document.createElement('button');
  const close = document.createElement('button');
  label.type = close.type = 'button';
  close.className = 'tabClose';
  close.textContent = '×';
  close.setAttribute('aria-label', 'Close browser tab');
  const tab = { chip, label, close, pane: null, dispose: null, section: 'home', draft: '' };
  setTitle(tab, 'Goop Home');
  label.onclick = () => selectTab(tab);
  close.onclick = () => closeTab(tab);
  chip.append(label, close);
  tabButtons.append(chip);
  tabs.push(tab);
  return tab;
}

function focusTab(tab) {
  if (selectedTab !== tab && selectedTab?.section === 'home') {
    selectedTab.draft = $('homeSearch').value;
  }
  selectedTab = tab;
  document.body.classList.toggle('webFocused', !!tab.pane);
  pageContent.hidden = !!tab.pane;
  webContent.hidden = !tab.pane;
  for (const item of tabs) {
    item.label.setAttribute('aria-pressed', String(item === tab));
    if (item.pane) item.pane.hidden = item !== tab;
  }
  const offset = tab.chip.getBoundingClientRect();
  const visible = tabButtons.getBoundingClientRect();
  if (offset.right > visible.right) tabButtons.scrollLeft += offset.right - visible.right;
  if (offset.left < visible.left) tabButtons.scrollLeft -= visible.left - offset.left;
}

function selectTab(tab) {
  if (tab.pane) focusTab(tab);
  else goopNavigate(tab.section, true, tab);
}

function selectSection(name, requestedTab) {
  const tab = requestedTab || (selectedTab && !selectedTab.pane ? selectedTab :
    tabs.find(item => !item.pane && item.section === name) || tabs.find(item => !item.pane)) || createTab();
  const switching = selectedTab !== tab;
  focusTab(tab);
  if (name === 'home' && switching) {
    hideResults();
    $('homeSearch').value = tab.draft;
  }
  if (tab.section !== name && tab.section === 'home') tab.draft = $('homeSearch').value;
  tab.section = name;
  setTitle(tab, name === 'home' ? 'Goop Home' :
    cats.find(category => category[0] === name)?.[1] || (name.slice(5).replaceAll('-', ' ')));
  return tab;
}

function closeTab(tab) {
  const index = tabs.indexOf(tab);
  if (index < 0) return;
  tabs.splice(index, 1);
  tab.dispose?.();
  tab.disposeApp?.();
  tab.pane?.remove();
  tab.chip.remove();
  if (selectedTab === tab) {
    selectedTab = null;
    const next = tabs[index] || tabs[index - 1] || createTab();
    selectTab(next);
    next.label.focus({preventScroll:true});
  }
}

document.getElementById('newWebTab').onclick = () => {
  goopNavigate('home', true, createTab());
  $('homeSearch').focus({preventScroll:true});
};

function navigate(initialUrl, game=null) {
  if (!game && openCatalogURL(initialUrl)) return;
  const tab = selectedTab?.section === 'home' && !selectedTab.pane ? selectedTab : createTab();
  const pane = document.getElementById('webTemplate').content.firstElementChild.cloneNode(true);
  const label = tab.label;
  focusTab(tab);
  tab.draft = $('homeSearch').value;
  tab.section = null;
  tab.pane = pane;
  webContent.append(pane);
  let closed = false, lastError = '', currentUrl = '', history = [], historyIndex = -1;
  function setup($) {
    const address = $('urlInput');
const isolatedOrigin = 'https://mathscholar.s3.dualstack.us-east-1.amazonaws.com';
const browserOrigin = location.origin === isolatedOrigin ? 'https://mathscholar.s3.amazonaws.com' : isolatedOrigin;
const hostedCopy = new URL('/Goop.svg', browserOrigin);
hostedCopy.searchParams.set('goop-runtime','web-3');
hostedCopy.hash = 'web-runtime-v1';
let browserFrame = null, connected = false, loaderTimer = 0, pageTimer = 0, legacy = false;
let navigationNumber = 0, awaitingFirstPage = false, effectiveTransport = settings.transport;
const webNotice = message => { $('status').textContent = message; };
function controls() {
  $('backBtn').disabled = historyIndex <= 0;
  $('forwardBtn').disabled = historyIndex + 1 >= history.length;
}
function syncAddress(url) {
  currentUrl = url;
  address.value = url;
  setTitle(tab, game?.name || new URL(url).hostname);
}
function accountUnavailable(displayed = false) {
  if (displayed) stopBrowser();
  clearTimeout(pageTimer);
  address.value = currentUrl;
  controls();
  webNotice('Sign-in is unavailable in this browser.');
}
function stopBrowser() {
  clearTimeout(loaderTimer); clearTimeout(pageTimer);
  $('browserStage').replaceChildren(); browserFrame = null; connected = false; legacy = false;
  navigationNumber++; awaitingFirstPage = false;
}
function appendFrame(target, onLoad) {
  if (target.origin !== browserOrigin || target.origin === location.origin) {
    throw Error('The browser needs its separate HTTPS origin.');
  }
  const frame = document.createElement('iframe');
  frame.dataset.part = 'browserFrame'; frame.title = 'Goop web browser';
  frame.referrerPolicy = 'no-referrer';
  frame.setAttribute('allow',"camera 'none'; microphone 'none'; geolocation 'none'");
  frame.setAttribute('sandbox','allow-scripts allow-same-origin allow-forms');
  frame.src = target.href;
  if (onLoad) frame.onload = onLoad;
  browserFrame = frame;
  $('browserStage').replaceChildren(frame);
  return frame;
}
function loadLegacy() {
  if (closed || !currentUrl) return;
  clearTimeout(loaderTimer);
  clearTimeout(pageTimer);
  connected = false;
  effectiveTransport = 'epoxy';
  legacy = true;
  const target = new URL('/nosw.html',browserOrigin);
  const encode = value => btoa(String.fromCharCode(...new TextEncoder().encode(value))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
  target.searchParams.set('goopRequest', String(navigationNumber));
  target.searchParams.set('go',encode(currentUrl));
  target.searchParams.set('w1',encode(wispAddress(settings.wisp,'epoxy')));
  appendFrame(target);
  webNotice('Epoxy via '+new URL(settings.wisp).host+' · If the page shows a connection error, open Connection to retry.');
}
function sendAddress() {
  clearTimeout(pageTimer);
  awaitingFirstPage = true;
  browserFrame.contentWindow.postMessage({kind:'goop-browse',url:currentUrl,serial:navigationNumber,
    transport:effectiveTransport, wisp:wispAddress(settings.wisp,effectiveTransport)},browserOrigin);
  pageTimer = setTimeout(loadLegacy, 35000);
}
function loadPage(url) {
  if (goopYouTube.isSignIn(url,currentUrl)) { accountUnavailable(); return; }
  if (!browserFrame) $('browserStage').replaceChildren();
  lastError=''; syncAddress(url); controls(); navigationNumber++;
  if(!settings.preferProxy){stopBrowser();webNotice('Web browsing is turned off. Enable “Use NoSW for browser navigation” in Settings to continue.');return;}
  try {wispAddress(settings.wisp,legacy ? 'epoxy' : settings.transport);} catch(error){stopBrowser();webNotice(error.message);return;}
  webNotice('Loading ' + new URL(url).hostname + '…');
  if (connected) { sendAddress(); return; }
  if (legacy) { loadLegacy(); return; }
  if (browserFrame) return;
  const frame = appendFrame(hostedCopy, () => {
    if (browserFrame === frame && !connected) {
      clearTimeout(loaderTimer);
      loaderTimer = setTimeout(loadLegacy,3500);
    }
  });
  frame.onerror = () => { if (browserFrame === frame && !connected) loadLegacy(); };
  loaderTimer = setTimeout(loadLegacy,14000);
}
function navigate(url) {
  const dest = safeUrl(url);
  if (!dest) { toast('Enter a valid web address'); return; }
  if (goopYouTube.isSignIn(dest,currentUrl)) { accountUnavailable(); return; }
  if (history[historyIndex] !== dest) { history.splice(historyIndex+1); history.push(dest); historyIndex = history.length-1; }
  loadPage(dest);
}
const onMessage = event=>{
  if (!browserFrame || closed || event.source !== browserFrame.contentWindow || event.origin !== browserOrigin) return;
  const m = event.data;
  if (!m || typeof m !== 'object') return;
  if (m.serial === navigationNumber && (m.kind === 'goop-account-unavailable' || m.kind === 'goop-youtube-signin')) {
    accountUnavailable(m.displayed === true || m.kind === 'goop-youtube-signin');
    return;
  }
  if (legacy) return;
  if (m.kind === 'goop-browser-ready') {
    clearTimeout(loaderTimer);
    if (!Array.isArray(m.transports)) { loadLegacy(); return; }
    const available = m.transports;
    if (available.includes(settings.transport)) effectiveTransport = settings.transport;
    else if (available.includes('epoxy')) effectiveTransport = 'epoxy';
    else { loadLegacy(); return; }
    connected = true; sendAddress(); return;
  }
  if (m.serial !== navigationNumber) return;
  if (m.kind === 'goop-web-error' && (m.reason === 'wisp' || m.reason === 'startup' || (!m.reason && awaitingFirstPage))) {
    loadLegacy();
    return;
  }
  if (m.kind === 'goop-web-notice') { webNotice(String(m.text||'').slice(0,200)); return; }
  if (m.kind === 'goop-web-error') {
    clearTimeout(pageTimer);
    lastError=String(m.text||'Could not load the page.').slice(0,350); webNotice('Could not load this page. '+String(m.text||'Check the Wisp server and retry.').slice(0,200));
    return;
  }
  if (m.kind === 'goop-web-page') {
    const url=safeUrl(m.url); if(!url)return;
    if (goopYouTube.isSignIn(url,currentUrl)) { accountUnavailable(true); return; }
    clearTimeout(pageTimer);
    if (awaitingFirstPage) { history[historyIndex]=url; awaitingFirstPage=false; }
    else if(history[historyIndex]!==url){history.splice(historyIndex+1);history.push(url);historyIndex=history.length-1;}
    syncAddress(url); controls(); webNotice(new URL(url).hostname+' · '+(effectiveTransport==='libcurl'?'Libcurl':'Epoxy'));
  }
};
