async function showGames(q=''){

  const n=$('categoryResults');n.replaceChildren();clearNotice();
  const sourceKey=gameSource;
  const loading=goopElement('p','Loading '+sources[sourceKey].label+' games…','muted');
  n.append(loading);
  try{
    const list=sourceKey==='multiplayer'?multiplayer:await catalog(sourceKey);
    if(gameSource!==sourceKey||active!=='category'||!loading.isConnected)return;
    const term=q.toLowerCase().trim();
    let matches=list.filter(g=>g.name.toLowerCase().includes(term));
    if(gameFavOnly)matches=matches.filter(g=>favorites.some(f=>f.source===sourceKey&&f.name===g.name));
    if(gameSort==='az')matches=[...matches].sort((a,b)=>a.name.localeCompare(b.name));
    else if(gameSort==='za')matches=[...matches].sort((a,b)=>b.name.localeCompare(a.name));
    else if(gameSort==='favs'||gameSort==='recent'){const pool=gameSort==='favs'?favorites:recent;const rank=g=>{const i=pool.findIndex(f=>f.source===sourceKey&&f.name===g.name);return i<0?1e9:i};matches=[...matches].sort((a,b)=>rank(a)-rank(b));}
    const limit=sourceKey==='fourgames'?350:140;
    const shown=matches.slice(0,limit);
    n.replaceChildren();
    if(!shown.length){notice(gameFavOnly&&!term?'No favorites in this catalog yet. Open a game and press Favorite.':'No games match your search.');return}
    shown.forEach(g=>{
      const cover=g.img&&!g.img.includes('placeholder')?gameCoverURL(sourceKey,g.img):null;
      const card=makeResult(g.name,sources[sourceKey].label,'',cover,
        ()=>void openGame({source:sourceKey,name:g.name}).catch(e=>toast(e.message)));
      n.append(card);
    });
    if(matches.length>limit&&!term)notice('Showing '+limit+' of '+matches.length+' games — search for more.');
  }catch(e){
    if(gameSource!==sourceKey||active!=='category'||!loading.isConnected)return;
    n.replaceChildren();
