/* ===== Goop additions: continue watching/reading shelves and keyboard shortcuts ===== */
const PROGRESS_KEY='goop-progress';
const MOVIE_PATH=/^\/api\/stream\/(?:movie\/\d+|tv\/\d+\/[^/]+\/[^/]+)$/;
function readProgress(){
  const p=read(PROGRESS_KEY,{});
  const movie=(Array.isArray(p.movie)?p.movie:[]).filter(x=>x&&typeof x.title==='string'&&Number.isSafeInteger(x.id)&&(x.type==='movie'||x.type==='tv')&&typeof x.path==='string'&&MOVIE_PATH.test(x.path));
  const manga=(Array.isArray(p.manga)?p.manga:[]).filter(x=>x&&typeof x.title==='string'&&typeof x.id==='string'&&x.id&&Number.isSafeInteger(x.index)&&x.index>=0);
  return {movie,manga};
}
function pushProgress(kind,entry){
  const p=readProgress();
  p[kind]=[entry,...p[kind].filter(x=>x.key!==entry.key)].slice(0,6);
  try{localStorage.setItem(PROGRESS_KEY,JSON.stringify(p))}catch{}
  drawProgress();
}
function chip(title,sub,fn){
  const b=document.createElement('button');b.type='button';b.className='btn';
  b.dataset.initial=title.trim().charAt(0).toUpperCase()||'?';
  const stack=document.createElement('span');stack.className='stack';
  const t=document.createElement('span');t.textContent=title;stack.append(t);
  if(sub){const s=document.createElement('small');s.textContent=sub;stack.append(s)}
  b.append(stack);
  b.onclick=()=>Promise.resolve().then(fn).catch(e=>toast(e.message||'Could not open that'));
  return b;
}
function drawProgress(){
  const {movie,manga}=readProgress();
  const w=$('watching'),r=$('reading');
  if(w){
    w.hidden=!movie.length;
    w.querySelector('.shelf').replaceChildren(...movie.map(e=>chip(e.title,e.label,async()=>{
      await goopOpenMovie({id:e.id,media_type:e.type,title:e.title});
      await goopPlayMovie(e.path);
    })));
  }
  if(r){
    r.hidden=!manga.length;
    r.querySelector('.shelf').replaceChildren(...manga.map(e=>chip(e.title,e.label,async()=>{
      await goopOpenManga({id:e.id,title:e.title});
      if(goopMangaChapters[e.index])await goopReadMangaChapter(e.index);
    })));
  }
}
