document.addEventListener('keydown',e=>{
  if(e.defaultPrevented||e.ctrlKey||e.metaKey||e.altKey||e.isComposing)return;
  if(document.body.classList.contains('webFocused'))return;
  const homeScreen=document.getElementById('homeScreen');
  if(!homeScreen||homeScreen.hidden)return;
  const t=e.target,typing=!!t&&(t.isContentEditable||/^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName));
  if(e.key==='Escape'){
    if(typing){t.blur();return}
    if(document.querySelector('dialog[open]'))return;
    if(document.querySelector('#goopMoviePanel:not(.hidden),#goopMangaOverlay,#goopMusicOverlay'))return;
    if(currentGame){$('goopGameBack').click();return}
    if(active==='category'||active==='settings')goopNavigate('home');
    return;
  }
  if(typing||document.querySelector('dialog[open]'))return;
  if(e.key==='/'){
    e.preventDefault();
    const box=active==='category'?$('categoryTools').querySelector('input'):$('homeSearch');
    (box||$('homeSearch')).focus();
    return;
  }
  if(e.key==='?'){e.preventDefault();shortcutHelp();return}
  if((e.key==='f'||e.key==='F')&&currentGame)$('goopGameFullscreen').click();
});

/* ===== Play counts and Trending ===== */
const PLAYED_KEY='goop-played';
const playsBase=()=>String(window.GOOP_BACKEND_URL||'').replace(/\/$/,'');
function recordPlay(g){
  try{
    if(!validGame(g)||!playsBase())return;
    const seen=read(PLAYED_KEY,{}),key=g.source+'|'+g.name,now=Date.now();
    if(now-(seen[key]||0)<30*60*1000)return;   // one count per game per 30 minutes
    seen[key]=now;
    for(const k of Object.keys(seen))if(now-seen[k]>86400000)delete seen[k];
    try{localStorage.setItem(PLAYED_KEY,JSON.stringify(seen))}catch{}
    const body=JSON.stringify({source:g.source,name:g.name});
    const url=playsBase()+'/api/plays/hit';
    if(!(navigator.sendBeacon&&navigator.sendBeacon(url,new Blob([body],{type:'text/plain'}))))
      fetch(url,{method:'POST',headers:{'Content-Type':'text/plain'},body,keepalive:true}).catch(()=>{});
  }catch{}
}
async function drawTrending(){
  const sec=$('trending');if(!sec||!playsBase())return;
  try{
    const r=await fetch(playsBase()+'/api/plays/trending',{signal:AbortSignal.timeout(8000)});
    if(!r.ok)return;
    const data=await r.json();
    const rows=(Array.isArray(data.games)?data.games:[]).filter(validGame);
    // Only show games that really exist in a catalog, so made-up names can't reach the home page.
    const real=await Promise.all(rows.map(async g=>{
      try{
        const list=g.source==='offline'?standaloneGames:await catalog(g.source);
        return list.some(x=>x.name===g.name)?g:null;
      }catch{return null}
    }));
    const shown=real.filter(Boolean).slice(0,8);
    sec.hidden=!shown.length;
    sec.querySelector('.shelf').replaceChildren(...shown.map(g=>chip(g.name,sources[g.source].label,()=>openGame(lite(g)))));
  }catch{}
}
setTimeout(drawTrending,0);

