;
window.goopPrograms["ai"] = function(root, signal) {
const find = id => root.querySelector('#'+id);
const models = [
  { name: 'Goop AI', model: 'SmolLM2-360M-Instruct', revision: '7be6f65f1db715fe5dc5a4634c0d459b4eed42ec', bytes: 270590880 },
  { name: 'SmolLM2 Mini', model: 'SmolLM2-135M-Instruct', revision: '09816acd5d99df7be770d85ea30822623dab342c', bytes: 105454432 },
  { name: 'Qwen 2.5', model: 'Qwen2.5-0.5B-Instruct', revision: '41ba88dbac95fed2528c92514c131d73eb5a174b', bytes: 397808192 }
];
const el = id => find(id);
const menu = el('model'), status = el('status'), log = el('log'), input = el('message');
for (const model of models) menu.add(new Option(model.name, model.model));
let thread = [], runtime = null, loaded = null, job = null;
const selected = () => models[menu.selectedIndex];
function describe() {
  const model = selected();
  status.textContent = model.name + ' uses ' + model.model + '. First use downloads about ' +
    Math.ceil(model.bytes / 1e6) + ' MB. Messages are processed on this device.';
}
function bubble(role, name, text) {
  const article = document.createElement('article'), author = document.createElement('strong'), body = document.createElement('p');
  article.dataset.role = role;
  author.textContent = name;
  body.textContent = text;
  article.append(author, body);
  log.append(article);
  log.scrollTop = log.scrollHeight;
  return body;
}
function reset() {
  thread = [];
  log.replaceChildren();
  describe();
}
menu.onchange = reset;
el('clear').onclick = reset;
el('stop').onclick = () => { job?.abort(); status.textContent = 'Stopping…'; };
input.onkeydown = e => {
  if (e.key === 'Enter' && !e.shiftKey && !e.isComposing) {
    e.preventDefault();
    if (!job) el('composer').requestSubmit();
  }
};
function controls(busy) {
  menu.disabled = el('clear').disabled = busy;
  el('send').hidden = busy;
  el('stop').hidden = !busy;
}
async function weights(model, signal) {
  const url = 'https:\/\/huggingface.co/bartowski/' + model.model + '-GGUF/resolve/' + model.revision + '/' + model.model + '-Q4_K_M.gguf';
  let cache;
  try { cache = await caches.open('goop-models-v1'); } catch {}
  const saved = await cache?.match(url);
  if (saved) {
    const blob = await saved.blob();
    if (blob.size === model.bytes) return blob;
    await cache.delete(url);
  }
  const response = await fetch(url, { signal, credentials: 'omit' });
  if (!response.ok) throw Error('Model download failed (HTTP ' + response.status + ').');
  const parts = [], reader = response.body.getReader();
  let received = 0, previous = -1;
  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    received += value.byteLength;
    if (received > model.bytes) { await reader.cancel(); throw Error('Unexpected model download size.'); }
    parts.push(value);
    const percent = Math.floor(100 * received / model.bytes);
    if (percent !== previous) status.textContent = 'Downloading ' + model.name + ' · ' + percent + '%';
    previous = percent;
  }
  if (received !== model.bytes) throw Error('The model download was interrupted. Please retry.');
  const blob = new Blob(parts);
  if (cache) { try { await cache.put(url, new Response(blob)); } catch {} }
  return blob;
}
async function load(model, signal) {
  if (runtime && loaded === model) return;
  if (runtime) { await runtime.exit(); runtime = loaded = null; }
  status.textContent = 'Preparing ' + model.name + '…';
  const { Wllama } = await import("data:text/javascript;base64,");
  const blob = await weights(model, signal);
  signal.throwIfAborted();
  status.textContent = 'Starting ' + model.name + '…';
  const instance = new Wllama({ 'single-thread/wllama.wasm': "data:application/wasm;base64," });
  try {
    await instance.loadModel([blob], { n_ctx: 2048, n_batch: 96, n_threads: 1 });
    signal.throwIfAborted();
  } catch (error) { await instance.exit().catch(() => {}); throw error; }
  runtime = instance;
  loaded = model;
}
async function contextFor(model, question) {
  const system = { role: 'system', content: 'You are ' + model.name + ', a helpful assistant inside Goop. Answer the user clearly and honestly.' };
  const messages = [system, ...thread.slice(-16), { role: 'user', content: question }];
  while (true) {
    const prompt = await runtime.formatChat(messages, true);
    if ((await runtime.tokenize(prompt, true)).length <= 1776) return messages;
    if (messages.length <= 2) throw Error('Please shorten your message so it fits this model.');
    messages.splice(1, 2);
  }
}
el('composer').onsubmit = async event => {
  event.preventDefault();
  const question = input.value.trim(), model = selected();
  if (!question || job) return;
  const controller = new AbortController();
  job = controller;
  controls(true);
  const user = bubble('user', 'You', question);
  let answer, completed = '';
  input.value = '';
  try {
    await load(model, controller.signal);
    const messages = await contextFor(model, question);
    controller.signal.throwIfAborted();
    answer = bubble('assistant', model.name, '');
    status.textContent = model.name + ' is answering…';
    completed = await runtime.createChatCompletion(messages, {
      nPredict: 240, sampling: { temp: 0.45 }, abortSignal: controller.signal,
      onNewToken: (_token, _piece, text) => {
        const follow = log.scrollHeight - log.scrollTop - log.clientHeight < 64;
        answer.textContent = text;
        if (follow) log.scrollTop = log.scrollHeight;
      }
    });
    completed = completed.trim();
    if (!completed) throw Error('The model returned an empty reply. Please try again.');
    answer.textContent = completed;
    thread.push({ role: 'user', content: question }, { role: 'assistant', content: completed });
    status.textContent = controller.signal.aborted ? 'Reply stopped.' : 'Ready';
  } catch (error) {
    if (answer?.textContent) {
      thread.push({ role: 'user', content: question }, { role: 'assistant', content: answer.textContent });
    } else {
      user.parentElement.remove();
      answer?.parentElement.remove();
      if (!input.value) input.value = question;
    }
    status.textContent = controller.signal.aborted ? 'Stopped.' : 'Could not finish: ' + (error.message || error);
  } finally {
    if(signal.aborted && runtime){await runtime.exit().catch(()=>{});runtime=null;} job = null; controls(false); input.focus(); }
};
describe();

signal.addEventListener('abort',()=>{ if(job)job.abort(); else if(runtime)void runtime.exit().catch(()=>{}); },{once:true});

};
;
window.goopPrograms["chat"] = function(root, signal) {
const find = id => root.querySelector('#'+id);

function voiceClient(api, display, ended) {
  let generation=0,stream=null,ticket='',timer,room='',servers=[],cursor=0,joining=false;
  const peers=new Map();
  const $=id=>find(id);
  const status=s=>{$('voiceStatus').textContent=s;};
  function controls(){
    $('joinVoice').hidden=!!ticket || joining;
    $('mic').hidden=!ticket;$('leaveVoice').hidden=!ticket && !joining;
    $('mic').textContent=stream?.getAudioTracks()[0]?.enabled?'Mute mic':'Unmute mic';
  }
  function drop(id){
    const p=peers.get(id);if(!p)return;
    peers.delete(id);p.pc.onicecandidate=null;p.pc.ontrack=null;p.pc.close();p.audio.remove();
  }
  function leave(tell=true){
    generation++;clearTimeout(timer);const old=ticket;
    ticket='';room='';joining=false;cursor=0;
    stream?.getTracks().forEach(t=>t.stop());stream=null;
    for(const id of peers.keys())drop(id);
    $('voicePeople').replaceChildren();$('playAudio').hidden=true;controls();
    if(tell && old)void api('voice/leave',{ticket:old}).catch(()=>{});
  }
  function peer(person){
    let p=peers.get(person.ticket);if(p)return p;
    const pc=new RTCPeerConnection({iceServers:servers});
    const audio=document.createElement('audio');audio.autoplay=true;$('audio').append(audio);
    p={pc,audio,candidates:[],out:Promise.resolve(),person};peers.set(person.ticket,p);
    const myTicket=ticket;
    function send(signal){
      p.out=p.out.then(async()=>{
        if(myTicket!==ticket || !peers.has(person.ticket))return;
        await api('voice/signal',{ticket:myTicket,to:person.ticket,signal});
      }).catch(e=>{if(ticket===myTicket && e.status!==410)status(e.message);});
    }
    p.send=send;
    stream.getAudioTracks().forEach(t=>pc.addTrack(t,stream));
    pc.ontrack=e=>{audio.srcObject=e.streams[0] || new MediaStream([e.track]);audio.play().catch(()=>{$('playAudio').hidden=false;});};
    pc.onicecandidate=e=>{if(e.candidate)send({...e.candidate.toJSON(),type:'candidate'});};
    pc.onconnectionstatechange=()=>{
      if(!ticket || !peers.has(person.ticket))return;
      if(pc.connectionState==='failed')status('Audio could not connect. Leave and rejoin. Some networks need a TURN relay.');
      else if(pc.connectionState==='connected')status('Voice connected');
    };
    return p;
  }
  async function poll(gen){
    if(gen!==generation||!ticket)return;
    try{
      const result=await api('voice/poll',{ticket,after:cursor});if(gen!==generation)return;
      if(result.peers.length && peers.size===0)status('Connecting audio…');
      const byTicket=new Map(result.peers.map(p=>[p.ticket,p]));
      for(const id of peers.keys())if(!byTicket.has(id))drop(id);
      for(const person of result.peers){
        if(peers.has(person.ticket))continue;
        const p=peer(person);
        if(ticket<person.ticket){
          const offer=await p.pc.createOffer();if(gen!==generation)return;
          await p.pc.setLocalDescription(offer);p.send({type:'offer',sdp:offer.sdp});
        }
      }
      for(const envelope of result.signals){
        if(gen!==generation)return;
        const p=peers.get(envelope.from),s=envelope.signal;
        if(p && envelope.seq>cursor){
          if(s.type==='candidate'){
            if(p.pc.remoteDescription)await p.pc.addIceCandidate(s);else p.candidates.push(s);
          }else{
            await p.pc.setRemoteDescription(s);
            for(const candidate of p.candidates.splice(0))await p.pc.addIceCandidate(candidate);
            if(s.type==='offer'){
              const answer=await p.pc.createAnswer();await p.pc.setLocalDescription(answer);
              p.send({type:'answer',sdp:answer.sdp});
            }
          }
        }
        cursor=Math.max(cursor,envelope.seq);
      }
      if(!byTicket.size)status('You are in voice. Waiting for someone to join.');
      display(result.peers,ticket);
    }catch(e){
      if(gen!==generation)return;
      if([401,403,410].includes(e.status)){leave(false);ended(e.message);return;}
      status(e.message);
    }
    if(gen===generation)timer=setTimeout(()=>poll(gen),800);
  }
  async function join(id){
    leave();const gen=generation;joining=true;controls();status('Allow microphone access to join.');
    try{
      if(!navigator.mediaDevices?.getUserMedia||!window.RTCPeerConnection)throw Error('Voice needs HTTPS and a browser with microphone support.');
      const mic=await navigator.mediaDevices.getUserMedia({audio:true,video:false});
      if(gen!==generation){mic.getTracks().forEach(t=>t.stop());return;}
      stream=mic;
      const result=await api('voice/join',{room:id});
      if(gen!==generation){void api('voice/leave',{ticket:result.ticket}).catch(()=>{});return;}
      ticket=result.ticket;servers=result.iceServers;room=id;joining=false;controls();status('Joining voice…');void poll(gen);
    }catch(e){
      if(gen!==generation)return;
      leave(false);ended(e.name==='NotAllowedError'?'Microphone access was denied. Allow it in your browser to join.':e.message);
    }
  }
  $('mic').onclick=()=>{for(const t of stream?.getAudioTracks()||[])t.enabled=!t.enabled;controls();};
  $('leaveVoice').onclick=()=>{leave();ended('You left voice.');};
  $('playAudio').onclick=async()=>{try{await Promise.all([...peers.values()].map(p=>p.audio.play()));$('playAudio').hidden=true;}catch{status('Your browser is blocking audio playback.');}};
  window.addEventListener('pagehide',()=>leave(),{signal});
  return {join,leave,get room(){return room;},get ticket(){return ticket;}};
}


const $=id=>find(id);

const base=window.GOOP_CHAT_URL || window.GOOP_BACKEND_URL;
let parentPort,visitConnection,canGoHome=false;
let continuation='',visit='',pageGeneration=0;
let token='',user=null,home=null,selection=null,version=0,authMode='signin',nextHome=0,busy=false;
let messageKey='',voiceKey='',navKey='',pending=null,polling=false,sessionVersion=0;
const drafts=new Map();
function node(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function button(text,fn){
  const b=node('button',text);b.type='button';b.addEventListener('click',async()=>{
    try{await fn();}catch(err){feedback(err.message);}
  });return b;
}
function feedback(message){($('tools').open?$('toolStatus'):$('notice')).textContent=message;}
async function api(path,data) {
  const usedToken=token;
  let res;
  try{
    res=await fetch(new URL('/api/chat/'+path,base),{method:data===undefined?'GET':'POST',cache:'no-store',credentials:'omit',
      headers:{...(usedToken?{Authorization:'Bearer '+usedToken}:{}),...(visit?{'X-Goop-Visit':visit}:{}),...(data===undefined?{}:{'Content-Type':'application/json'})},
      body:data===undefined?undefined:JSON.stringify(data),signal:AbortSignal.timeout(16000)});
  }catch {throw Error('Cannot reach the Goop chat server. Check this site’s origin in Settings > Chat connection and the gateway status.');}
  const result=await res.json().catch(()=>null);
  if(!res.ok || !result){
    if(res.status===401 && usedToken && token===usedToken) signedOut('Your session ended. Sign in again.');
    throw Object.assign(Error(result?.error || (res.status===404?'This gateway needs the Goop accounts update.':'Chat server returned HTTP '+res.status+'.')),{status:res.status});
  }
  return result;
}
function errorText(id,msg){$(id).textContent=msg;}
function mode(next){
  continuation='';authMode=next;
  $('username').maxLength=next==='signin'?256:24;
  $('username').autocomplete='username';
  $('password').required=next!=='signin';
  const signup=next==='signup',reset=next==='recover';
  $('authTitle').textContent=signup?'Create an account':reset?'Reset password':'Welcome back';
  $('authIntro').textContent=signup?'Choose a username and a passphrase.':reset?'Use the recovery key you saved.':'Sign in to Goop Chat.';
  $('emailField').hidden=$('email').disabled=!signup;
  $('keyField').hidden=$('recoveryInput').disabled=!reset;$('recoveryInput').required=reset;
  $('passwordLabel').textContent=reset?'New password':'Password';
  $('password').minLength=signup||reset?15:1;
  $('password').placeholder=signup||reset?'At least 15 characters':'';
  $('password').autocomplete=signup||reset?'new-password':'current-password';
  $('password').value='';$('recoveryInput').value='';$('email').value='';
  $('forgot').hidden=signup||reset;
  $('submitAuth').textContent=signup?'Create account':reset?'Reset password':'Sign in';
  $('switchLead').textContent=signup||reset?'Have an account?':'New to Goop?';
  $('authSwitch').textContent=signup||reset?'Sign in':'Create an account';errorText('authError','');
}
$('authSwitch').onclick=()=>mode(authMode==='signin'?'signup':'signin');
$('forgot').onclick=()=>mode('recover');
