  messageKey=navKey=voiceKey='';pending=null;drafts.clear();$('text').value='';$('messages').replaceChildren();
  $('tools').close();$('toolBody').replaceChildren();$('recoveryKey').textContent='';$('recovery').hidden=$('app').hidden=true;
