async function manageRoles(){
  const wrap=dialog('Manage roles');
  const {roles}=await api('roles');
  if(!$('tools').open || $('toolTitle').textContent!=='Manage roles' || !user?.admin)return;
  let roleSelect;
  actionForm(wrap,'Create role',f=>{
