window.goopPrograms["game-2048"] = function(root, signal) {
const find = id => root.querySelector('#'+id);
let a,score;const b=find('board');function reset(){a=Array.from({length:4},()=>Array(4).fill(0));score=0;spawn();spawn();render()}function spawn(){let free=[];a.forEach((row,y)=>row.forEach((v,x)=>{if(!v)free.push([y,x])}));if(!free.length)return;let [y,x]=free[Math.random()*free.length|0];a[y][x]=Math.random()<.9?2:4}function combine(row){let vals=row.filter(Boolean),out=[];for(let i=0;i<vals.length;i++){if(vals[i]===vals[i+1]){out.push(vals[i]*2);score+=vals[i]*2;i++}else out.push(vals[i])}while(out.length<4)out.push(0);return out}function move(key){let old=JSON.stringify(a);for(let i=0;i<4;i++){let v;if(key==='ArrowLeft'||key==='ArrowRight'){v=a[i].slice();if(key==='ArrowRight')v.reverse();v=combine(v);if(key==='ArrowRight')v.reverse();a[i]=v}else{v=a.map(r=>r[i]);if(key==='ArrowDown')v.reverse();v=combine(v);if(key==='ArrowDown')v.reverse();v.forEach((x,j)=>a[j][i]=x)}}if(JSON.stringify(a)!==old){spawn();render()}}function render(){try{localStorage.setItem('goop-save:game-2048',JSON.stringify({board:a,score}));}catch{}b.replaceChildren();a.flat().forEach(v=>{const el=document.createElement('div');el.className='cell';el.style.cssText='width:78px;height:78px;background:'+(v?'#326e40':'#162c1c')+';font-size:'+(v>1000?'21':'27')+'px';el.textContent=v||'';b.append(el)});find('score').textContent=score}document.addEventListener('keydown',e=>{if(root.hidden||document.body.classList.contains('webFocused')||e.target.closest('input,textarea,dialog'))return;let k={w:'ArrowUp',s:'ArrowDown',a:'ArrowLeft',d:'ArrowRight'}[e.key]||e.key;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(k)){e.preventDefault();move(k)}},{signal});let start;root.addEventListener('touchstart',e=>{start=[e.touches[0].clientX,e.touches[0].clientY]},{passive:true});root.addEventListener('touchend',e=>{if(!start)return;let x=e.changedTouches[0].clientX-start[0],y=e.changedTouches[0].clientY-start[1];if(Math.max(Math.abs(x),Math.abs(y))<25)return;move(Math.abs(x)>Math.abs(y)?(x>0?'ArrowRight':'ArrowLeft'):(y>0?'ArrowDown':'ArrowUp'));start=null});let saved;try{saved=JSON.parse(localStorage.getItem('goop-save:game-2048'));}catch{}
if(saved?.board?.length===4 && saved.board.every(row=>Array.isArray(row)&&row.length===4&&row.every(n=>Number.isSafeInteger(n)&&n>=0)) && Number.isSafeInteger(saved.score)){a=saved.board;score=saved.score;render();}else reset();
root.querySelector('[data-game-reset]').onclick=reset;

};
;
window.goopPrograms["game-snake"] = function(root, signal) {
const find = id => root.querySelector('#'+id);
const c=find('game'),ctx=c.getContext('2d'),N=20;let snake,dir,next,food,score,alive;function place(){do{food=[Math.floor(Math.random()*N),Math.floor(Math.random()*N)]}while(snake.some(p=>p[0]===food[0]&&p[1]===food[1]))}function restart(){snake=[[10,10],[9,10],[8,10]];dir=[1,0];next=dir;score=0;alive=true;find('score').textContent=score;place();draw()}function input(x,y){if(x!==-dir[0]||y!==-dir[1])next=[x,y]}document.addEventListener('keydown',e=>{if(root.hidden||document.body.classList.contains('webFocused')||e.target.closest('input,textarea,dialog'))return;let m={ArrowUp:[0,-1],ArrowDown:[0,1],ArrowLeft:[-1,0],ArrowRight:[1,0],w:[0,-1],s:[0,1],a:[-1,0],d:[1,0]}[e.key];if(m){e.preventDefault();input(...m)}},{signal});let start; c.addEventListener('touchstart',e=>{start=[e.touches[0].clientX,e.touches[0].clientY]},{passive:true});c.addEventListener('touchend',e=>{if(!start)return;let x=e.changedTouches[0].clientX-start[0],y=e.changedTouches[0].clientY-start[1];if(Math.max(Math.abs(x),Math.abs(y))<20)return;Math.abs(x)>Math.abs(y)?input(Math.sign(x),0):input(0,Math.sign(y));start=null});function draw(){ctx.fillStyle='#071009';ctx.fillRect(0,0,400,400);ctx.fillStyle='#b9ffce';ctx.fillRect(food[0]*20+3,food[1]*20+3,14,14);snake.forEach((p,i)=>{ctx.fillStyle=i===0?'#b2ffbd':'#3acd6c';ctx.fillRect(p[0]*20+1,p[1]*20+1,18,18)});if(!alive){ctx.fillStyle='#fff';ctx.font='bold 28px sans-serif';ctx.textAlign='center';ctx.fillText('Game Over',200,190)}}function tick(){if(!alive||root.hidden||document.body.classList.contains('webFocused')||document.hidden)return;dir=next;const h=[snake[0][0]+dir[0],snake[0][1]+dir[1]];const eat=h[0]===food[0]&&h[1]===food[1];if(h.some(v=>v<0||v>=20)||snake.slice(0,eat?undefined:-1).some(p=>p[0]===h[0]&&p[1]===h[1])){alive=false;draw();return}snake.unshift(h);if(eat){score++;find('score').textContent=score;place()}else snake.pop();draw()}restart();const clock=setInterval(tick,130);signal.addEventListener('abort',()=>clearInterval(clock),{once:true});
root.querySelector('[data-game-reset]').onclick=restart;

};
;
window.goopPrograms["game-tic-tac-toe"] = function(root, signal) {
const find = id => root.querySelector('#'+id);
let cells=Array(9).fill(''),turn='X',end=false;const b=find('board'),msg=find('info');function reset(){cells.fill('');turn='X';end=false;msg.textContent='Your turn: X';draw()}function draw(){try{localStorage.setItem('goop-save:game-tic-tac-toe',JSON.stringify({cells,turn,end,message:msg.textContent}));}catch{}b.replaceChildren();cells.forEach((v,i)=>{const el=document.createElement('button');el.textContent=v;el.style.cssText='height:90px;font-size:38px';el.onclick=()=>play(i);b.append(el)})}function play(i){if(cells[i]||end)return;cells[i]=turn;const win=[[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]].some(x=>x.every(j=>cells[j]===turn));if(win){msg.textContent=turn+' wins!';end=true}else if(cells.every(Boolean)){msg.textContent='Draw!';end=true}else{turn=turn==='X'?'O':'X';msg.textContent='Your turn: '+turn}draw()}try{const saved=JSON.parse(localStorage.getItem('goop-save:game-tic-tac-toe'));
if(saved?.cells?.length===9&&saved.cells.every(c=>['','X','O'].includes(c))&&['X','O'].includes(saved.turn)&&typeof saved.end==='boolean'){cells=saved.cells;turn=saved.turn;end=saved.end;msg.textContent=String(saved.message||'').slice(0,50);}}catch{}draw();
root.querySelector('[data-game-reset]').onclick=reset;

};
;

(() => {
  'use strict';
  function start() {
    const nav = document.getElementById('goopNav');
    const page = document.getElementById('goopPage');
    const homePanel = document.getElementById('homeScreen');
    const navLinks = [...nav.querySelectorAll('[data-goop-section]')];
    const base=new URL(location.href);base.hash='';navLinks.find(a=>a.dataset.goopSection==='home').href=base.href;
    const valid = new Set(navLinks.map(link => link.dataset.goopSection));
    const sheets = [...document.querySelectorAll('style[data-screen]')];
    const templates = new Map([...document.querySelectorAll('template[data-screen]')].map(t => [t.dataset.screen, t]));
    for (const name of templates.keys()) valid.add(name);
    let current = 'home', activeScreen = 'home', homeRoute, activeRoot;
    let manualChanges = 0;
    let chatRoot;
    function route(name) { return valid.has(name) ? name : 'home'; }
    window.goopOpenInvite = game => homeRoute.openGame(game, game.roomUrl);
    function draw(name, requestedTab) {
      const tab = homeRoute.selectSection(name, requestedTab);
      const app = templates.has(name) ? name : 'home';
      if (tab.nativeScreen !== app) tab.disposeApp?.();
      let root = app === 'chat' ? chatRoot : tab.nativeRoot;
      if (activeRoot && activeRoot !== root) activeRoot.hidden = true;
      if (activeScreen === 'home' && app !== 'home') homeRoute.leave();
      homePanel.hidden = app !== 'home';
      for (const sheet of sheets) sheet.media = sheet.dataset.screen === app ? 'all' : 'not all';
      if (app !== 'home' && !root) {
        root = document.createElement('div');
        root.append(templates.get(app).content.cloneNode(true));
        page.append(root);
        const controller = new AbortController();
        if (app === 'chat') chatRoot = root;
        else {
          tab.nativeRoot = root;
          tab.nativeScreen = app;
          tab.disposeApp = () => {
            controller.abort(); root.remove();
            tab.nativeRoot = tab.nativeScreen = tab.disposeApp = null;
          };
        }
        window.goopPrograms[app](root, controller.signal);
        if (app.startsWith('game-')) {
          const game = {source:'offline', name:{'game-2048':'2048','game-snake':'Snake','game-tic-tac-toe':'Tic Tac Toe'}[app]};
          homeRoute.remember(game);
          homeRoute.gameTools(root,game);
        }
      }
      if (root) root.hidden = false;
      activeRoot = root;
      activeScreen = app;
      current = name;
      document.body.dataset.page = name;
      if (app === 'home') {homeRoute.show(name);homeRoute.drawShelf();}
      const item = name.startsWith('game-') ? 'games' : name;
      for (const link of navLinks) {
        if (link.dataset.goopSection === item) link.setAttribute('aria-current','page');
        else link.removeAttribute('aria-current');
      }
      window.scrollTo(0, 0);
    }
    const api = window.google?.script;
    function writeRoute(name, replace) {
      const home = name === 'home';
      const state = {view:name};
      try {
        if (api?.history) {
          const params = home ? {} : state;
          if (replace) api.history.replace(state, params, '');
          else api.history.push(state, params, '');
        } else if (window.top === window.self) {
          const url = new URL(location.href);url.hash=home?'':name;
          if (replace) history.replaceState(state, '', url);
          else history.pushState(state, '', url);
        }
      } catch { /* The page still works when the host blocks history changes. */ }
    }
    function go(name, record = true, requestedTab) {
      name = route(name);
      const changed = name !== current;
      if (record) manualChanges++;
      draw(name, requestedTab);
      if (record && (changed || name === 'home')) writeRoute(name, !changed);
    }
    function clicked(event) {
      const link = event.target.closest('[data-goop-section]');
      if (!link || !valid.has(link.dataset.goopSection)) return;
      event.preventDefault();
      go(link.dataset.goopSection);
    }
    nav.addEventListener('click', clicked);
    document.getElementById('categories').addEventListener('click', clicked);
    homeRoute = window.goopPrograms.home(homePanel, go);
    function localLocation() {
      return {hash:location.hash.slice(1), parameter:Object.fromEntries(new URLSearchParams(location.search))};
    }
    function restore(loc) {
      const params = loc?.parameter || {};
      const name = loc?.hash || params.view;
      if (name === 'browser' && params.q) {
        go('home', false);
        homeRoute.search(params.q);
        return;
      }
      go(name, false);
      if (name === 'home') writeRoute('home', true);
    }
    function restoreInitial(loc) {
      const name = loc.parameter?.view;
      if (loc.hash || name) restore(loc);
    }
    go('home', false);
    if (api?.history && api?.url) {
      api.history.setChangeHandler(event => { manualChanges++; restore(event.location); });
      const generation = manualChanges;
      api.url.getLocation(loc => {
        if (generation === manualChanges) restoreInitial(loc);
      });
    } else {
      restoreInitial(localLocation());
      window.addEventListener('popstate', () => restore(localLocation()));
      window.addEventListener('hashchange', () => {
        const loc = localLocation();
        if (loc.hash === 'home' || route(loc.hash || loc.parameter.view) !== current) restore(loc);
      });
    }
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start, {once:true});
  else start();
})();

(()=>{'use strict';
const $=id=>document.getElementById(id);
const get=(k,f)=>{try{const v=localStorage.getItem(k);return v===null?f:v}catch{return f}};
const put=(k,v)=>{try{localStorage.setItem(k,v)}catch{}};
const json=(k,f)=>{try{const v=JSON.parse(get(k,''));return v&&typeof v==='object'?v:f}catch{return f}};

/* ---------- Theme ---------- */
const THEMES=['goop','midnight','ember','matrix'];
const themeSel=$('goopTheme'),matrixOpts=$('matrixOptions');
function applyTheme(t){
  if(!THEMES.includes(t))t='goop';
  document.documentElement.dataset.theme=t;
  if(matrixOpts)matrixOpts.hidden=t!=='matrix';
  if(themeSel)themeSel.value=t;
}
applyTheme(get('goop-theme','goop'));
themeSel?.addEventListener('change',()=>{put('goop-theme',themeSel.value);applyTheme(themeSel.value)});

/* ---------- Tab disguise (your own title and icon, or a plain preset) ---------- */
const svgIcon=svg=>'data:image/svg+xml,'+encodeURIComponent(svg);
const PRESETS={
  none:{title:'',icon:''},
  doc:{title:'Untitled document',icon:svgIcon("<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'><rect x='6' y='3' width='20' height='26' rx='3' fill='#4f8cf0'/><path d='M10 11h12M10 16h12M10 21h8' stroke='white' stroke-width='2' stroke-linecap='round'/></svg>")},
  newtab:{title:'New Tab',icon:svgIcon("<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'><rect x='3' y='3' width='26' height='26' rx='6' fill='#7b8794'/><path d='M16 9v14M9 16h14' stroke='white' stroke-width='2.5' stroke-linecap='round'/></svg>")},
  notes:{title:'Notes',icon:svgIcon("<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'><rect x='5' y='3' width='22' height='26' rx='3' fill='#f2c94c'/><path d='M10 11h12M10 16h12M10 21h7' stroke='#6b5410' stroke-width='2' stroke-linecap='round'/></svg>")},
  calc:{title:'Calculator',icon:svgIcon("<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'><rect x='5' y='3' width='22' height='26' rx='3' fill='#3b4252'/><rect x='9' y='7' width='14' height='5' rx='1' fill='#9fb4c7'/><g fill='white'><circle cx='11' cy='17' r='1.6'/><circle cx='16' cy='17' r='1.6'/><circle cx='21' cy='17' r='1.6'/><circle cx='11' cy='23' r='1.6'/><circle cx='16' cy='23' r='1.6'/><circle cx='21' cy='23' r='1.6'/></g></svg>")}
};
const cloakPreset=$('goopCloakPreset'),cloakTitle=$('goopCloakTitle'),cloakIcon=$('goopCloakIcon'),cloakCustom=$('goopCloakCustom');
let cloak=json('goop-cloak',{preset:'none',title:'',icon:''});
let wantedTitle='';
function cloakValues(){
  const p=cloak.preset||'none';
  if(p==='custom'){
    const icon=typeof cloak.icon==='string'&&/^https?:\/\//i.test(cloak.icon)?cloak.icon:'';
    return {title:String(cloak.title||'').slice(0,60),icon};
  }
  return PRESETS[p]||PRESETS.none;
}
function applyCloak(){
  const v=cloakValues();
  wantedTitle=v.title;
  document.title=v.title||'Goop';
  document.querySelectorAll('link[data-goop-cloak]').forEach(l=>l.remove());
  if(v.icon){
    const link=document.createElement('link');
    link.rel='icon';link.href=v.icon;link.dataset.goopCloak='';
    document.head.append(link);
  }
  if(cloakCustom)cloakCustom.hidden=(cloak.preset||'none')!=='custom';
}
if(cloakPreset){
  cloakPreset.value=cloak.preset||'none';
  if(cloakTitle)cloakTitle.value=cloak.title||'';
  if(cloakIcon)cloakIcon.value=cloak.icon||'';
  const save=()=>{
    cloak={preset:cloakPreset.value,title:cloakTitle?.value||'',icon:cloakIcon?.value||''};
    put('goop-cloak',JSON.stringify(cloak));applyCloak();
  };
  cloakPreset.addEventListener('change',save);
  cloakTitle?.addEventListener('input',save);
  cloakIcon?.addEventListener('change',save);
}
applyCloak();
const titleEl=document.querySelector('title');
if(titleEl)new MutationObserver(()=>{if(wantedTitle&&document.title!==wantedTitle)document.title=wantedTitle}).observe(titleEl,{childList:true,characterData:true,subtree:true});

/* ---------- Panic key ---------- */
const panicBtn=$('goopPanicKey'),panicClear=$('goopPanicClear'),panicUrl=$('goopPanicUrl'),panicStatus=$('goopPanicStatus');
let panic=json('goop-panic',{key:''});
let capturing=false;
const RESERVED=new Set(['/','?','f','F','Escape','Tab','Enter']);
const note=m=>{if(panicStatus)panicStatus.textContent=m||''};
function label(){
  if(!panicBtn)return;
  panicBtn.textContent=panic.key?'Panic key: '+(panic.key===' '?'Space':panic.key):'Set a key';
}
function panicTarget(){
  try{const u=new URL(get('goop-panic-url','')||'https://www.google.com');return ['http:','https:'].includes(u.protocol)?u.href:'https://www.google.com'}
  catch{return 'https://www.google.com'}
}
label();
if(panicUrl){
  panicUrl.value=get('goop-panic-url','');
  panicUrl.addEventListener('change',()=>{
    const v=panicUrl.value.trim();
    if(v&&!/^https?:\/\//i.test(v)){note('Use a full address that starts with https://');return}
    put('goop-panic-url',v);note(v?'Saved.':'Using google.com.');
  });
}
panicBtn?.addEventListener('click',()=>{capturing=true;panicBtn.textContent='Press a key…';note('')});
panicClear?.addEventListener('click',()=>{panic={key:''};put('goop-panic',JSON.stringify(panic));capturing=false;label();note('Panic key is off.')});
document.addEventListener('keydown',e=>{
  if(capturing){
    e.preventDefault();e.stopPropagation();
    capturing=false;
    if(e.key==='Escape'){label();return}
    if(RESERVED.has(e.key)||e.key.length>1&&!/^F\d{1,2}$/.test(e.key)&&e.key!==' '){
      label();note('That key is used elsewhere. Try another one.');return;
    }
    panic={key:e.key};put('goop-panic',JSON.stringify(panic));label();
    note('Saved. If a game has focus, click outside it first.');
    return;
  }
  if(!panic.key||e.repeat||e.key!==panic.key||e.ctrlKey||e.metaKey||e.altKey)return;
  const t=e.target,typing=!!t&&(t.isContentEditable||/^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName));
  if(typing&&/^[a-z0-9]$/i.test(e.key))return;
  e.preventDefault();
  location.replace(panicTarget());
},true);

/* ---------- Announcement banner ----------
   Edit the id and text to post something new. Bumping the id shows it again
   to everyone, even people who dismissed the last one. Set text to '' to hide it. */
const ANNOUNCEMENT={
  id:'redesign-2026-11',
  text:'Goop has a new look. Pick a theme in Settings, and press / to jump to search.'
};
const bar=$('goopAnnounce');
if(bar&&ANNOUNCEMENT.text&&get('goop-announce-dismissed','')!==ANNOUNCEMENT.id){
  const p=document.createElement('p');p.textContent=ANNOUNCEMENT.text;
  const x=document.createElement('button');x.type='button';x.textContent='Dismiss';
  x.addEventListener('click',()=>{put('goop-announce-dismissed',ANNOUNCEMENT.id);bar.hidden=true});
  bar.replaceChildren(p,x);bar.hidden=false;
}
})();
